/bin/zsh -lc "cat > outputs/app/tokens.css <<'EOF'
@font-face{font-family:Plex;src:url('fonts/plex-sans-latin.woff2') format('woff2');font-weight:100 700;font-display:swap}
@font-face{font-family:PlexMono;src:url('fonts/plex-mono-400-latin.woff2') format('woff2');font-weight:400;font-display:swap}
:root{
 --bg:#EEF1F4;--surface:#FFFFFF;--fg:#263747;--muted:#566675;--brand:#12355B;--line:#C9D2DB;--soft:#E4EAF0;
 --critical:#A52D38;--critical-bg:#FFF0F0;--caution:#85440E;--caution-bg:#FFF3E6;--healthy:#18685F;--chart:#2A9D8F;--orange:#F26B21;--focus:#12355B;--white:#FFFFFF;
 --sans:Plex,Arial,sans-serif;--mono:PlexMono,monospace;
 --fs-xs:12px;--fs-sm:14px;--fs-body:16px;--fs-row:16px;--fs-title:24px;--fs-brand:25px;--fs-number:54px;--fs-clock:26px;--fs-dialog:28px;
 --s1:4px;--s2:8px;--s3:12px;--s4:16px;--s5:20px;--s6:24px;--s7:32px;--s8:40px;--s9:48px;--gutter:32px;
 --radius:4px;--round:50%;--hair:1px;--rule:3px;--focus-width:3px;--zero:0;--full:100%;--touch:44px;--header:80px;--status:52px;--metric:144px;--sidebar:300px;--row:76px;--dialog-width:660px;--shadow:0 16px 64px #00000040;--backdrop:#081727B8;
 --duration:120ms;--ease:ease-out;--no-motion:0s;--weight:400;--medium:500;--bold:600;--lineheight:1.4;--tight:1.15;--caps:.08em;--wordmark:-.035em;
}
:root[data-theme=dark]{
 --bg:#0E1C2A;--surface:#142637;--fg:#E4EBF1;--muted:#A5B5C4;--brand:#C2D9EE;--line:#3E5264;--soft:#1D3347;
 --critical:#FFABB2;--critical-bg:#38232F;--caution:#F3BF8C;--caution-bg:#342C25;--healthy:#89D1C4;--chart:#2A9D8F;--orange:#F26B21;--focus:#C2D9EE;--white:#FFFFFF;
 --shadow:0 16px 64px #00000040;--backdrop:#081727B8;
}
:root[data-display=tv]{--fs-xs:14px;--fs-sm:16px;--fs-body:18px;--fs-row:19px;--fs-title:26px;--fs-brand:28px;--fs-number:64px;--fs-clock:30px;--gutter:48px;--header:88px;--metric:156px;--sidebar:350px;--row:72px}
EOF
cat > outputs/app/style.css <<'EOF'
*{box-sizing:border-box}body{margin:var(--zero);background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:var(--fs-body);line-height:var(--lineheight)}button,input,select{font:inherit}button,a,input,select{ -webkit-tap-highlight-color:transparent}button{cursor:pointer}button:disabled{cursor:default;opacity:.45}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:var(--focus-width) solid var(--focus);outline-offset:var(--s1)}button{color:inherit}a{color:var(--brand)}.skip{position:fixed;top:var(--s2);left:var(--s2);padding:var(--s3);background:var(--surface);z-index:5;transform:translateY(-200%)}.skip:focus{transform:none}header{height:var(--header);display:flex;justify-content:space-between;align-items:center;padding:var(--zero) var(--gutter);background:var(--surface);border-bottom:var(--hair) solid var(--line)}.identity{display:flex;align-items:center;gap:var(--s6)}.wordmark{font-size:var(--fs-brand);font-weight:var(--bold);letter-spacing:var(--wordmark);color:var(--brand)}.wordmark small{display:block;font-size:var(--fs-xs);letter-spacing:var(--caps);font-weight:var(--medium);text-transform:uppercase;margin-top:calc(var(--s1)*-1)}h1{font-size:var(--fs-body);font-weight:var(--medium);border-left:var(--hair) solid var(--line);padding-left:var(--s6);margin:var(--zero)}.clock{text-align:right;font-size:var(--fs-sm);color:var(--muted)}.clock strong{font-family:var(--mono);font-size:var(--fs-clock);color:var(--fg);margin-right:var(--s4);font-weight:var(--weight)}.statusbar{min-height:var(--status);display:flex;align-items:center;gap:var(--s3);padding:var(--s2) var(--gutter);color:var(--healthy);border-bottom:var(--hair) solid var(--line);font-size:var(--fs-sm)}.statusbar strong{font-weight:var(--bold)}.statusbar .dot{width:var(--s2);height:var(--s2);border-radius:var(--round);background:currentColor}.statusbar .status-detail{color:var(--muted)}.statusbar .source{margin-left:auto;color:var(--muted);font-size:var(--fs-xs)}.stale .statusbar{color:var(--caution);background:var(--caution-bg);border-bottom-color:var(--caution)}.stale .status-detail{color:var(--caution)}main{padding:var(--zero) var(--gutter)}.metrics{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:var(--hair) solid var(--line);min-height:var(--metric);padding:var(--s6) var(--zero)}.metric{padding:var(--zero) var(--s7);border-left:var(--hair) solid var(--line)}.metric:first-child{padding-left:var(--zero);border-left:var(--zero)}.metric-label{font-size:var(--fs-sm);color:var(--muted);font-weight:var(--medium);margin:var(--zero)}.metric-value{font-family:var(--mono);font-size:var(--fs-number);line-height:var(--tight);letter-spacing:var(--wordmark);display:inline-block;color:var(--brand);margin:var(--s1) var(--zero)}.metric-note{font-size:var(--fs-sm);color:var(--muted)}.metric-note .improved{color:var(--healthy)}.metric-note .critical{color:var(--critical);font-weight:var(--bold)}.workspace{display:grid;grid-template-columns:minmax(0,1fr) var(--sidebar);gap:var(--s8);padding-top:var(--s6)}h2{font-size:var(--fs-title);font-weight:var(--bold);line-height:var(--tight);margin:var(--zero)}.section-head{display:flex;align-items:center;gap:var(--s4);justify-content:space-between;min-height:var(--touch);margin-bottom:var(--s4)}.section-head h2 span{font-family:var(--mono);color:var(--muted);font-size:var(--fs-body);font-weight:var(--weight);margin-left:var(--s2)}.tools{display:flex;gap:var(--s2)}input,select{background:var(--surface);border:var(--hair) solid var(--line);border-radius:var(--radius);min-height:var(--touch);color:var(--fg);padding:var(--s2) var(--s3);font-size:var(--fs-sm)}input{width:180px}input::placeholder{color:var(--muted)}select{max-width:150px}.table-wrap{min-width:var(--zero)}table{border-collapse:collapse;width:var(--full);table-layout:fixed;text-align:left}caption{position:absolute;width:var(--hair);height:var(--hair);overflow:hidden;clip-path:inset(50%)}thead{color:var(--muted);font-size:var(--fs-xs)}th{font-weight:var(--medium);padding:var(--s2) var(--s3);border-bottom:var(--hair) solid var(--line)}th:first-child,td:first-child{padding-left:var(--s3)}td{height:var(--row);padding:var(--s3);border-bottom:var(--hair) solid var(--line);font-size:var(--fs-sm);vertical-align:middle}th.severity-col{width:8%}th.incident-col{width:40%}th.status-col{width:15%}th.command-col{width:17%}th.time-col{width:20%}.sev{font-family:var(--mono);font-size:var(--fs-sm);font-weight:var(--weight);white-space:nowrap}.sev1{color:var(--critical)}.sev2{color:var(--caution)}.sev3{color:var(--muted)}tr.urgent{background:var(--critical-bg)}tr.urgent td:first-child{box-shadow:inset var(--rule) 0 var(--critical)}.incident-button{font-size:var(--fs-row);line-height:var(--tight);font-weight:var(--medium);background:none;border:var(--zero);padding:var(--zero);text-align:left;min-height:var(--s6)}.incident-button:hover{text-decoration:underline;text-underline-offset:var(--s1)}.meta{font-size:var(--fs-xs);color:var(--muted);margin-top:var(--s1)}.mono{font-family:var(--mono)}.commander-missing{color:var(--critical);font-weight:var(--bold)}.duration{font-family:var(--mono);font-size:var(--fs-sm);white-space:nowrap}.opened{display:block;color:var(--muted);font-size:var(--fs-xs);margin-top:var(--s1)}.pagination{display:flex;align-items:center;justify-content:space-between;min-height:var(--touch);margin-top:var(--s2);color:var(--muted);font-size:var(--fs-sm)}.page-buttons{display:flex;align-items:center;gap:var(--s2)}.plain-button{background:var(--surface);border:var(--hair) solid var(--line);border-radius:var(--radius);min-height:var(--touch);padding:var(--s2) var(--s4);font-size:var(--fs-sm)}.plain-button:hover:not(:disabled){background:var(--soft)}.empty{padding:var(--s9) var(--s4);text-align:center}.empty button{margin-top:var(--s4)}aside{border-left:var(--hair) solid var(--line);padding-left:var(--s7)}aside h2{font-size:var(--fs-body);margin-bottom:var(--s5)}.oncall{padding-bottom:var(--s6);border-bottom:var(--hair) solid var(--line)}.oncall dl{margin:var(--zero)}.oncall dt{font-size:var(--fs-xs);color:var(--muted);margin-top:var(--s4)}.oncall dd{font-size:var(--fs-body);margin:var(--s1) var(--zero) var(--zero);font-weight:var(--medium)}.oncall .until{font-size:var(--fs-xs);font-weight:var(--weight);color:var(--muted)}.assignment{display:flex;gap:var(--s2);font-size:var(--fs-sm);margin:var(--s5) var(--zero) var(--zero);color:var(--critical)}.services{padding-top:var(--s6)}.services h2{margin-bottom:var(--s2)}.services>p{color:var(--muted);font-size:var(--fs-xs);margin:var(--zero) var(--zero) var(--s5)}.service{margin-bottom:var(--s4)}.service-label{display:flex;justify-content:space-between;gap:var(--s2);font-size:var(--fs-sm);margin-bottom:var(--s2)}.bar-track{height:var(--s1);background:var(--soft)}.bar-fill{height:var(--full);background:var(--chart)}.resolved{border-top:var(--hair) solid var(--line);margin-top:var(--s5);padding-top:var(--s5)}.resolved h2{font-size:var(--fs-body);margin-bottom:var(--s4)}.resolved-grid{display:grid;grid-template-columns:1fr 1fr;gap:var(--s7)}.resolved-item{border-left:var(--rule) solid var(--line);padding-left:var(--s4)}.resolved-item .incident-button{font-size:var(--fs-sm)}footer{display:flex;justify-content:space-between;gap:var(--s4);padding:var(--s5) var(--gutter);color:var(--muted);font-size:var(--fs-xs)}dialog{width:min(var(--dialog-width),90vw);border:var(--hair) solid var(--line);border-radius:var(--radius);background:var(--surface);color:var(--fg);box-shadow:var(--shadow);padding:var(--s7)}dialog::backdrop{background:var(--backdrop)}.dialog-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:var(--s5)}dialog h2{font-size:var(--fs-dialog);margin-bottom:var(--s6)}dialog dl{display:grid;grid-template-columns:1fr 1fr;gap:var(--s5);margin:var(--zero)}dialog dt{font-size:var(--fs-sm);color:var(--muted)}dialog dd{margin:var(--s1) var(--zero) var(--zero)}.dialog-note{border-top:var(--hair) solid var(--line);padding-top:var(--s5);color:var(--muted);font-size:var(--fs-sm);margin-top:var(--s6)}.sr-only{position:absolute;width:var(--hair);height:var(--hair);padding:var(--zero);overflow:hidden;clip-path:inset(50%);white-space:nowrap}.tv-only{display:none}[data-display=tv] .tv-only{display:inline}[data-display=tv] .laptop-only{display:none}[data-display=tv] .section-head{margin-bottom:var(--s3)}[data-display=tv] .workspace{gap:var(--s9)}[data-display=tv] .resolved{margin-top:var(--s4);padding-top:var(--s4)}[data-display=tv] .resolved h2{margin-bottom:var(--s2)}[data-display=tv] footer{padding-top:var(--s4)}
@media(max-width:1000px){.workspace{grid-template-columns:1fr}aside{border-left:var(--zero);padding-left:var(--zero);display:grid;grid-template-columns:1fr 1fr;gap:var(--s7)}.services{padding-top:var(--zero)}.oncall{border-bottom:var(--zero)}.clock strong{display:block;margin-right:var(--zero)}.statusbar .source{display:none}.tools{flex-wrap:wrap}th.command-col{width:18%}th.incident-col{width:37%}}
@media(max-width:650px){:root{--gutter:16px;--fs-number:40px;--fs-title:22px}.identity{gap:var(--s3)}h1{padding-left:var(--s3);font-size:var(--fs-sm)}.clock{display:none}.metrics{grid-template-columns:1fr 1fr;gap:var(--s5)}.metric:nth-child(3){border-left:var(--zero);padding-left:var(--zero)}.metric{padding-left:var(--s4)}.section-head{align-items:flex-start;flex-direction:column}.table-wrap{overflow-x:auto}table{min-width:760px}aside,.resolved-grid{grid-template-columns:1fr}.statusbar{flex-wrap:wrap}.status-detail{display:block}.source{display:none}footer{flex-direction:column}}
@media(prefers-reduced-motion:reduce){*{animation-duration:var(--no-motion)"'!important;transition-duration:var(--no-motion)!important;scroll-behavior:auto!important}}
EOF
cat > outputs/app/index.html <<'"'EOF'
<"'!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Northwind · Incident operations</title><script>const params=new URLSearchParams(location.search);document.documentElement.dataset.theme=['"'light','dark'].includes(params.get('theme'))?params.get('theme'):(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light');document.documentElement.dataset.display=params.get('display')==='tv'?'tv':'laptop';</script><link rel=\"stylesheet\" href=\"tokens.css\"><link rel=\"stylesheet\" href=\"style.css\"><script src=\"fixtures.js\" defer></script><script src=\"app.js\" defer></script></head><body><div id=\"app\"></div></body></html>
EOF
cat > outputs/app/app.js <<'EOF'
'use strict';
const F=window.EVAL_FIXTURES.dashboard;
const screen=['live','stale','surge'].includes(params.get('screen'))?params.get('screen'):'live';
const tv=document.documentElement.dataset.display==='tv';
const all=F.incidents.slice(0,screen==='surge'?F.surgeCount:F.openCount);
let page=0,query='',severity='all';
const esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));
const count=s=>all.filter(i=>i.severity===s).length;
const app=document.querySelector('#app');
app.className=screen;
app.innerHTML="'`
<a class="skip" href="#incidents">Skip to open incidents</a>
<header><div class="identity"><div class="wordmark">Northwind<small>Logistics</small></div><h1>Incident operations</h1></div><div class="clock"><strong>${F.displayTime}<span class="sr-only"> local display time</span></strong>${F.displayDate}</div></header>
<div class="statusbar" role="status"><span class="dot" aria-hidden="true"></span>${screen==='"'stale'?"'`<strong>Updates interrupted</strong><span class="status-detail">Last received ${F.staleAsOf} · 1h 18m old. Values may have changed.</span>`:`<strong>Current snapshot</strong><span class="status-detail">As of ${F.displayTime}${screen==='"'surge'?' · Elevated incident volume':''}</span>"'`}<span class="source">${screen==='"'stale'?'Snapshot retained':'Operations overview'}</span></div>
<main>
<section class=\"metrics\" aria-label=\"Incident metrics"'${screen==='"'stale'?' from last received snapshot':''}\">
<div class=\"metric\"><h2 class=\"metric-label\">Open incidents</h2><div class=\"metric-value\" id=\"open\">"'${all.length}</div><div class="metric-note"><span class="critical">${count(1)} SEV1</span> · ${count(2)} SEV2 · ${count(3)} SEV3</div></div>
<div class="metric"><h2 class="metric-label">Mean time to resolve <span>· 7d</span></h2><div class="metric-value">${F.mttr}</div><div class="metric-note"><span class="improved">↓ ${F.mttrChange}</span> vs last week</div></div>
<div class="metric"><h2 class="metric-label">Pages today</h2><div class="metric-value">${F.pages}</div><div class="metric-note">↑ ${F.pagesDelta} vs yesterday</div></div>
<div class="metric"><h2 class="metric-label">SLO budget left</h2><div class="metric-value">${F.slo}</div><div class="metric-note">↓ ${F.sloChange}</div></div>
</section>
<div class="workspace"><section id="incidents" tabindex="-1" aria-labelledby="incident-heading"><div class="section-head"><h2 id="incident-heading">Open incidents <span>${all.length}</span></h2><div class="tools laptop-only"><label class="sr-only" for="search">Search open incidents</label><input id="search" type="search" placeholder="Search incidents…" autocomplete="off"><label class="sr-only" for="severity">Filter by severity</label><select id="severity"><option value="all">All severities</option><option value="1">SEV1</option><option value="2">SEV2</option><option value="3">SEV3</option></select></div><span class="tv-only metric-note">Severity first · oldest within severity</span></div>
<div class="table-wrap"><table><caption>Open incidents. Mitigated and monitoring incidents remain open.</caption><thead><tr><th scope="col" class="severity-col">Severity</th><th scope="col" class="incident-col">Incident / service</th><th scope="col" class="status-col">Status</th><th scope="col" class="command-col">Commander</th><th scope="col" class="time-col">Duration / opened</th></tr></thead><tbody id="incident-rows"></tbody></table><div id="empty" class="empty" hidden>No open incidents match these filters.<br><button class="plain-button" id="clear">Clear filters</button></div></div><div class="pagination"><span id="result-count" aria-live="polite"></span><div class="page-buttons" ${tv&&all.length>7?'"'':'hidden'}><button class=\"plain-button\" id=\"previous\" aria-label=\"Previous incident page\">← Previous</button><button class=\"plain-button\" id=\"next\" aria-label=\"Next incident page\">Next →</button></div></div>
</section>
<aside aria-label=\"Operational context\"><section class=\"oncall\"><h2>On call now</h2><dl><dt>Primary</dt><dd>"'${esc(F.primary)}</dd><dt>Secondary</dt><dd>${esc(F.secondary)}</dd></dl><p class="until">Both on call until ${F.until}</p><p class="assignment"><span aria-hidden="true">↳</span><span>SEV1 commander unassigned</span></p></section><section class="services"><h2>Incidents by service</h2><p>Last 30 days · incident count</p>${F.services.map(s=>`<div class="service"><div class="service-label"><span>${esc(s.name)}</span><span class="mono">${s.value}</span></div><div class="bar-track" aria-hidden="true"><div class="bar-fill" style="width:${s.value/14*100}%"></div></div></div>`).join('"'')}</section></aside></div>
<section class=\"resolved\" aria-labelledby=\"resolved-heading\"><h2 id=\"resolved-heading\">Recently resolved <span class=\"meta\">· "'${F.resolved.length} incidents</span></h2><div class="resolved-grid">${F.resolved.map(i=>`<article class="resolved-item"><button class="incident-button" data-incident="${i.id}" aria-label="View ${i.id}: ${esc(i.title)}">${esc(i.title)}</button><div class="meta"><span class="mono">${i.id}</span> · ${esc(i.service)} · SEV${i.severity} · Resolved</div><div class="meta">Opened ${i.opened} · Duration <span class="mono">${i.duration}</span></div></article>`).join('"'')}</div></section>
</main><footer><span>Northwind Incidents · Offline snapshot"'${screen==='"'stale'?"'` · All values as of ${F.staleAsOf}`:'"''}</span><span>"'${screen==='"'live'?'Open incidents ↑ 2 vs yesterday · ':''}Mitigated and monitoring incidents count as open</span></footer>
<dialog aria-labelledby=\"detail-title\"><div class=\"dialog-top\"><span id=\"detail-id\" class=\"mono\"></span><button id=\"close-dialog\" class=\"plain-button\" aria-label=\"Close incident details\">Close ×</button></div><div id=\"detail-body\"></div></dialog>"'`;
function renderRows(){
 const filtered=all.filter(i=>(severity==='"'all'||i.severity===Number(severity))&&"'`${i.id} ${i.title} ${i.service} ${i.commander||'"'unassigned'} "'${i.status}`.toLowerCase().includes(query.toLowerCase()));
 const visible=tv?filtered.slice(page*7,page*7+7):filtered;
 document.querySelector('"'#incident-rows').innerHTML=visible.map(i=>"'`<tr class="${i.severity===1?'"'urgent':''}\"><td><span class=\"sev sev"'${i.severity}">SEV${i.severity}</span></td><td><button class="incident-button" data-incident="${i.id}" aria-label="View ${i.id}: ${esc(i.title)}">${esc(i.title)}</button><div class="meta"><span class="mono">${i.id}</span> · ${esc(i.service)}</div></td><td>${i.status}</td><td class="${i.commander?'"'':'commander-missing'}\">"'${esc(i.commander||'"'Unassigned')}</td><td><span class=\"duration\">"'${i.duration}</span><span class="opened">${i.opened}</span></td></tr>`).join('"'');
 document.querySelector('#empty').hidden=filtered.length>0;
 document.querySelector('#result-count').textContent=tv&&filtered.length>7?"'`Showing ${page*7+1}–${Math.min(page*7+7,filtered.length)} of ${filtered.length} · ${page===0?`${filtered.length-7} more open incidents`:'"'Last page'}"'`:`${filtered.length} ${filtered.length===1?'"'incident':'incidents'}"'${query||severity!=='"'all'?"'` of ${all.length}`:'"' · All open statuses included'}"'`;
 document.querySelector('"'#previous').disabled=page===0;
 document.querySelector('#next').disabled=(page+1)*7>=filtered.length;
}
renderRows();
document.querySelector('#search').addEventListener('input',e=>{query=e.target.value;page=0;renderRows()});
document.querySelector('#severity').addEventListener('change',e=>{severity=e.target.value;page=0;renderRows()});
document.querySelector('#clear').addEventListener('click',()=>{query='';severity='all';document.querySelector('#search').value='';document.querySelector('#severity').value='all';renderRows();document.querySelector('#search').focus()});
for(const [id,delta] of [['previous',-1],['next',1]])document.querySelector('#'+id).addEventListener('click',()=>{page+=delta;renderRows();document.querySelector('#'+(delta===1?'previous':'next')).focus()});
const dialog=document.querySelector('dialog');let opener;
app.addEventListener('click',e=>{const button=e.target.closest('[data-incident]');if("'!button)return;opener=button;const i=[...all,...F.resolved].find(x=>x.id===button.dataset.incident);document.querySelector('"'#detail-id').textContent=i.id;document.querySelector('#detail-body').innerHTML="'`<h2 id="detail-title">${esc(i.title)}</h2><dl>${[['"'Service',i.service],['Severity',"'`SEV${i.severity}`],['"'Status',i.status],['Commander',i.status==='Resolved'?'Not recorded':i.commander||'Unassigned'],['Opened',i.opened],['Duration',i.duration]].map(([k,v])=>"'`<div><dt>${k}</dt><dd class="${k==='"'Commander'&&"'!i.commander&&i.status!=='"'Resolved'?'commander-missing':''}\">"'${esc(v)}</dd></div>`).join('"'')}</dl><p class=\"dialog-note\">"'${screen==='"'stale'?"'`Updates interrupted. Last received ${F.staleAsOf}. `:'"''}Read-only incident snapshot · "'${F.displayDate}</p>`;dialog.showModal()});
document.querySelector('"'#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',e=>{if("'!['"'light','dark'].includes(params.get('theme')))document.documentElement.dataset.theme=e.matches?'dark':'light'});
EOF"

