cat > outputs/app/app.js <<'EOF'
'use strict';
const F=window.EVAL_FIXTURES.dashboard;
const screen=['live','stale','surge'].includes(params.get('screen'))?params.get('screen'):'live';
const tv=document.documentElement.dataset.display==='tv';
const all=F.incidents.slice(0,screen==='surge'?F.surgeCount:F.openCount);
let page=0,query='',severity='all';
const esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));
const count=s=>all.filter(i=>i.severity===s).length;
const app=document.querySelector('#app');
app.className=screen;
app.innerHTML="'`
<a class="skip" href="#incidents">Skip to open incidents</a>
<header><div class="identity"><div class="wordmark">Northwind<small>Logistics</small></div><h1>Incident operations</h1></div><div class="clock"><strong>${F.displayTime}<span class="sr-only"> local display time</span></strong>${F.displayDate}</div></header>
<div class="statusbar" role="status"><span class="dot" aria-hidden="true"></span>${screen==='"'stale'?"'`<strong>Updates interrupted</strong><span class="status-detail">Last received ${F.staleAsOf} · 1h 18m old. Values may have changed.</span>`:`<strong>Current snapshot</strong><span class="status-detail">As of ${F.displayTime}${screen==='"'surge'?' · Elevated incident volume':''}</span>"'`}<span class="source">${screen==='"'stale'?'Snapshot retained':'Operations overview'}</span></div>
<main>
