function renderRows(){
 const filtered=all.filter(i=>(severity==='"'all'||i.severity===Number(severity))&&"'`${i.id} ${i.title} ${i.service} ${i.commander||'"'unassigned'} "'${i.status}`.toLowerCase().includes(query.toLowerCase()));
 const visible=tv?filtered.slice(page*7,page*7+7):filtered;
 document.querySelector('"'#incident-rows').innerHTML=visible.map(i=>"'`<tr class="${i.severity===1?'"'urgent':''}\"><td><span class=\"sev sev"'${i.severity}">SEV${i.severity}</span></td><td><button class="incident-button" data-incident="${i.id}" aria-label="View ${i.id}: ${esc(i.title)}">${esc(i.title)}</button><div class="meta"><span class="mono">${i.id}</span> · ${esc(i.service)}</div></td><td>${i.status}</td><td class="${i.commander?'"'':'commander-missing'}\">"'${esc(i.commander||'"'Unassigned')}</td><td><span class=\"duration\">"'${i.duration}</span><span class="opened">${i.opened}</span></td></tr>`).join('"'');
 document.querySelector('#empty').hidden=filtered.length>0;
 document.querySelector('#result-count').textContent=tv&&filtered.length>7?"'`Showing ${page*7+1}–${Math.min(page*7+7,filtered.length)} of ${filtered.length} · ${page===0?`${filtered.length-7} more open incidents`:'"'Last page'}"'`:`${filtered.length} ${filtered.length===1?'"'incident':'incidents'}"'${query||severity!=='"'all'?"'` of ${all.length}`:'"' · All open statuses included'}"'`;
 document.querySelector('"'#previous').disabled=page===0;
 document.querySelector('#next').disabled=(page+1)*7>=filtered.length;
}
renderRows();
document.querySelector('#search').addEventListener('input',e=>{query=e.target.value;page=0;renderRows()});
document.querySelector('#severity').addEventListener('change',e=>{severity=e.target.value;page=0;renderRows()});
document.querySelector('#clear').addEventListener('click',()=>{query='';severity='all';document.querySelector('#search').value='';document.querySelector('#severity').value='all';renderRows();document.querySelector('#search').focus()});
for(const [id,delta] of [['previous',-1],['next',1]])document.querySelector('#'+id).addEventListener('click',()=>{page+=delta;renderRows();document.querySelector('#'+(delta===1?'previous':'next')).focus()});
const dialog=document.querySelector('dialog');let opener;
app.addEventListener('click',e=>{const button=e.target.closest('[data-incident]');if("'!button)return;opener=button;const i=[...all,...F.resolved].find(x=>x.id===button.dataset.incident);document.querySelector('"'#detail-id').textContent=i.id;document.querySelector('#detail-body').innerHTML="'`<h2 id="detail-title">${esc(i.title)}</h2><dl>${[['"'Service',i.service],['Severity',"'`SEV${i.severity}`],['"'Status',i.status],['Commander',i.status==='Resolved'?'Not recorded':i.commander||'Unassigned'],['Opened',i.opened],['Duration',i.duration]].map(([k,v])=>"'`<div><dt>${k}</dt><dd class="${k==='"'Commander'&&"'!i.commander&&i.status!=='"'Resolved'?'commander-missing':''}\">"'${esc(v)}</dd></div>`).join('"'')}</dl><p class=\"dialog-note\">"'${screen==='"'stale'?"'`Updates interrupted. Last received ${F.staleAsOf}. `:'"''}Read-only incident snapshot · "'${F.displayDate}</p>`;dialog.showModal()});
document.querySelector('"'#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',e=>{if("'!['"'light','dark'].includes(params.get('theme')))document.documentElement.dataset.theme=e.matches?'dark':'light'});
EOF"

